      "อาหารมีกลิ่นหอมขึ้น ไก่กินมากขึ้น แต่แร่ธาตุถูกทำลาย",
      "อาหารเกาะเป็นก้อน กลิ่นสดหายไปมีกลิ่นโคลน ไขมัน กรดอะมิโน และวิตามินถูกทำลาย",
      "อาหารเป็นผงละเอียด ไม่มีกลิ่น และพลังงานเพิ่มขึ้นจากการหมัก"
